package dev.zomboid.installer;
import java.io.*;import java.nio.file.*;import java.util.*;import java.util.function.*;import java.util.zip.*;
/** Offline, composable pack builder: structured folders or loose mod/pack files. */
public final class Lego {
 private final Path root;private final Map<String,Path> sources=new LinkedHashMap<>();private final Map<String,String> settings=new LinkedHashMap<>();private final Consumer<String> progress;private String mode="update";
 private Lego(Path root,Consumer<String> progress){this.root=root;this.progress=progress;}
 private void add(Path file,String relative)throws IOException {relative=Engine.safeName(relative);Path previous=sources.get(relative.toLowerCase(Locale.ROOT));if(previous!=null&&!Engine.sha(previous).equals(Engine.sha(file)))throw new IOException("Dos archivos diferentes tienen el mismo nombre: "+relative+". Conserva solo uno.");Path dest=root.resolve(relative);Files.createDirectories(dest.getParent());Files.copy(file,dest,StandardCopyOption.REPLACE_EXISTING);sources.put(relative.toLowerCase(Locale.ROOT),dest);progress.accept(relative);}
 private static String kindZip(Path file)throws IOException {try(ZipFile zip=new ZipFile(file.toFile())){boolean data=false,assets=false,shaders=false,structured=false,metadata=zip.getEntry("pack.mcmeta")!=null;for(var entries=zip.entries();entries.hasMoreElements();){String name=entries.nextElement().getName();data|=name.startsWith("data/");assets|=name.startsWith("assets/");shaders|=name.startsWith("shaders/");structured|=name.startsWith("mods/")||name.startsWith("config/")||name.startsWith("resourcepacks/")||name.startsWith("shaderpacks/")||name.startsWith("datapacks/");}if(structured)return "";if(!metadata&&!shaders)return "";if(data&&assets)throw new IOException("Este ZIP contiene data y assets: colócalo manualmente en datapacks o resourcepacks.");if(data)return "datapacks";if(assets)return "resourcepacks";if(shaders)return "shaderpacks";return "";}}
 private void options(Path file)throws IOException {for(String line:Files.readAllLines(file)){int n=line.indexOf(':');if(n>0){String key=line.substring(0,n);if(key.startsWith("key_")||Set.of("guiScale","resourcePacks","incompatibleResourcePacks").contains(key))settings.put(key,line.substring(n+1));}}}
 private void folder(Path input)throws IOException {if(Set.of("mods","config","resourcepacks","shaderpacks","datapacks").contains(input.getFileName().toString())){try(var paths=Files.walk(input)){for(Path p:paths.filter(Files::isRegularFile).toList()){if(Files.isSymbolicLink(p))throw new IOException("Enlace no permitido");add(p,input.getFileName()+"/"+input.relativize(p).toString().replace('\\','/'));}}return;}if(Files.isSymbolicLink(input))throw new IOException("No se admiten enlaces en componentes");if(Files.exists(input.resolve("pack.json"))){Engine.Pack pack=Engine.load(input);if(pack.mode().equals("full"))mode="full";settings.putAll(pack.options());for(Engine.Entry f:pack.files()){Path file=input.resolve(f.path());if(!Files.isRegularFile(file)||!Engine.sha(file).equals(f.sha256()))throw new IOException("Componente alterado: "+f.path());add(file,f.path());}return;}
  if(Files.isRegularFile(input.resolve("manifest.json"))&&!Files.isDirectory(input.resolve("mods"))){Map<String,Object> cf=Json.object(Json.parse(Files.readString(input.resolve("manifest.json"))));if(cf.get("files") instanceof List<?> files&&!files.isEmpty())throw new IOException("Esta exportación CurseForge solo contiene referencias a mods. Añade sus JAR reales o usa Exportar instancia.");}
  String packKind=Files.isRegularFile(input.resolve("pack.mcmeta"))&&Files.isDirectory(input.resolve("assets"))?"resourcepacks":Files.isRegularFile(input.resolve("pack.mcmeta"))&&Files.isDirectory(input.resolve("data"))?"datapacks":Files.isDirectory(input.resolve("shaders"))?"shaderpacks":"";
  if(!packKind.isBlank()){try(var paths=Files.walk(input)){for(Path p:paths.filter(Files::isRegularFile).toList()){if(Files.isSymbolicLink(p))throw new IOException("Enlace no permitido");add(p,packKind+"/"+input.getFileName()+"/"+input.relativize(p).toString().replace('\\','/'));}}return;}
  try(var paths=Files.list(input)){for(Path p:paths.sorted().toList()){String name=p.getFileName().toString();if(Files.isDirectory(p)){if(Set.of("mods","config","resourcepacks","shaderpacks","datapacks").contains(name)){try(var files=Files.walk(p)){for(Path f:files.filter(Files::isRegularFile).toList()){if(Files.isSymbolicLink(f))throw new IOException("Enlace no permitido");add(f,name+"/"+p.relativize(f).toString().replace('\\','/'));}}}else if(!Set.of("saves","logs","libraries","versions","assets","downloads","natives","backups","crash-reports","screenshots",".git",".zomboid-installer").contains(name))folder(p);}else input(p);}}
 }
 private void input(Path file)throws IOException {if(Files.isSymbolicLink(file))throw new IOException("Enlace no permitido");if(Files.isDirectory(file)){folder(file);return;}String name=file.getFileName().toString(),lower=name.toLowerCase(Locale.ROOT);if(lower.equals("options.txt")){options(file);return;}if(lower.startsWith("launcher_")||lower.equals("accounts.json")||lower.equals("usercache.json")||lower.equals("pack.json")||lower.equals("minecraftinstance.json")||lower.equals("mmc-pack.json")||lower.equals("manifest.json")||lower.equals("launcher_profiles.json")||lower.equals("tlauncherprofiles.json"))return;
  if(lower.endsWith(".jar")){add(file,"mods/"+name);return;}if(lower.endsWith(".zip")){String kind=kindZip(file);if(!kind.isBlank()){add(file,kind+"/"+name);return;}Path unpack=Files.createTempDirectory("zomboid-lego-");try{long total=0;int count=0;try(ZipInputStream zip=new ZipInputStream(Files.newInputStream(file))){ZipEntry e;while((e=zip.getNextEntry())!=null){if(e.isDirectory())continue;if(++count>30000)throw new IOException("ZIP con demasiados archivos");Path out=unpack.resolve(Engine.safeName(e.getName()));Files.createDirectories(out.getParent());try(OutputStream sink=Files.newOutputStream(out)){byte[] b=new byte[65536];int n;while((n=zip.read(b))>=0){total+=n;if(total>16L*1024*1024*1024)throw new IOException("ZIP demasiado grande");sink.write(b,0,n);}}}}folder(unpack);}finally{Engine.removeTree(unpack);}return;}
  if(lower.endsWith(".toml")||lower.endsWith(".cfg")||lower.endsWith(".properties")||lower.endsWith(".ini")||lower.endsWith(".json"))add(file,"config/"+name);
 }
 public static Engine.Pack assemble(Engine.Pack current,List<Path> inputs,Path workspace,Consumer<String> progress)throws IOException {Path root=workspace.resolve("lego-"+UUID.randomUUID());Files.createDirectories(root);Lego builder=new Lego(root,progress);try{if(current!=null)builder.folder(current.root());for(Path input:inputs)builder.input(input);Engine.writeManifest(root,"ZOMBIES POLDO · modular",builder.mode,"1.21.1","21.1.255",null);Map<String,Object> manifest=Json.object(Json.parse(Files.readString(root.resolve("pack.json"))));manifest.put("options",builder.settings);Files.writeString(root.resolve("pack.json"),Json.write(manifest));Engine.Pack result=Engine.load(root);if(result.files().isEmpty())throw new IOException("No se encontraron mods, packs ni configuración reconocibles. Añade JAR, ZIP o las carpetas mods/config/resourcepacks/shaderpacks/datapacks.");return result;}catch(Exception e){Engine.removeTree(root);throw e;}}
 public static void save(Engine.Pack pack,Path target)throws IOException {if(pack.files().isEmpty())throw new IOException("Añade componentes antes de guardar el pack.");Path temp=Files.createTempFile(target.toAbsolutePath().getParent(),"zomboid-pack-",".zip");try{try(ZipOutputStream zip=new ZipOutputStream(Files.newOutputStream(temp))){List<String> entries=new ArrayList<>();entries.add("pack.json");pack.files().forEach(f->entries.add(f.path()));for(String relative:entries){Path file=pack.root().resolve(relative);zip.putNextEntry(new ZipEntry(relative));Files.copy(file,zip);zip.closeEntry();}}Files.move(temp,target,StandardCopyOption.REPLACE_EXISTING);}finally{Files.deleteIfExists(temp);}}
}
